 47	    public void updateStatus(Xpb98Status newStatus) {
 48	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
 49	            this.status = newStatus;
 50	        } else {
 51	            throw new IllegalStateException(
 52	                    "Cannot transition from " + this.status + " to " + newStatus
 53	            );
 54	        }
 55	    }
 56	}
 57	package com.fream.back.domain.m12.entity;
 58	
 59	public enum Xpb98Status {
 60	    PENDING {
 61	        @Override
 62	        public boolean canTransitionTo(Xpb98Status nextStatus) {
 63	            return nextStatus == SHIPPED || nextStatus == CANCELED;
 64	        }
 65	    },
 66	    SHIPPED {
 67	        @Override
 68	        public boolean canTransitionTo(Xpb98Status nextStatus) {
 69	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
 70	        }
 71	    },
 72	    IN_TRANSIT {
 73	        @Override
 74	        public boolean canTransitionTo(Xpb98Status nextStatus) {
 75	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
 76	                    || nextStatus == DELIVERED;
 77	        }
 78	    },
 79	    OUT_FOR_DELIVERY {
 80	        @Override
 81	        public boolean canTransitionTo(Xpb98Status nextStatus) {
 82	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
 83	        }
 84	    },
 85	    DELIVERED {
 86	        @Override
 87	        public boolean canTransitionTo(Xpb98Status nextStatus) {
 88	            return false;
 89	        }
 90	    },
 91	    RETURNED {
 92	        @Override
 93	        public boolean canTransitionTo(Xpb98Status nextStatus) {
 94	            return nextStatus == CANCELED;
 95	        }
 96	    },
 97	    CANCELED {
 98	        @Override
 99	        public boolean canTransitionTo(Xpb98Status nextStatus) {
100	            return false;
101	        }
102	    },
103	    DELAYED {
104	        @Override
105	        public boolean canTransitionTo(Xpb98Status nextStatus) {
106	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
107	        }
108	    },
109	    FAILED_DELIVERY {
110	        @Override
111	        public boolean canTransitionTo(Xpb98Status nextStatus) {
112	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
113	        }
114	    };
115	
116	    public abstract boolean canTransitionTo(Xpb98Status nextStatus);
117	}

