112	    public void processPaymentAndShipment(Long orderId, String userEmail, Xrt49RequestDto requestDto) {
113	        if (orderId == null) {
114	            throw new Xcz21Exception("주문 ID가 없습니다.");
115	        }
116	        if (userEmail == null || userEmail.trim().isEmpty()) {
117	            throw new Xxf47Exception("사용자 정보가 없습니다.");
118	        }
119	        if (requestDto == null) {
120	            throw new Xtj87Exception("결제 및 배송 정보가 없습니다.");
121	        }
122	
123	        try {
124	
125	            Xrd81 user = userQueryService.findByEmail(userEmail);
126	            Xdg64 order = orderRepository.findById(orderId)
127	                    .orElseThrow(() -> new Xks61Exception("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
128	
129	
130	            if (!order.getUser().getId().equals(user.getId())) {
131	                throw new Xxf47Exception("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
132	            }
133	
134	
135	            validatePaymentShipmentRequest(requestDto);
136	
137	            try {
138	
139	                Xbf54 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
140	                order.assignPayment(payment);
141	            } catch (Exception e) {
142	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
143	                throw new Xqj91Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
144	            }
145	
146	            try {
147	
148	                Xhx14 shipment = orderShipmentCommandService.createOrderShipment(
149	                        order,
150	                        requestDto.getReceiverName(),
151	                        requestDto.getReceiverPhone(),
152	                        requestDto.getPostalCode(),
153	                        requestDto.getAddress()
154	                );
155	                order.assignOrderShipment(shipment);
156	            } catch (Exception e) {
157	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
158	                throw new Xmz95Exception("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
159	            }
160	
161	            try {
162	
163	                if (requestDto.isWarehouseStorage()) {
164	
165	                    order.updateStatus(Xdg64Status.PAYMENT_COMPLETED);
166	                    order.updateStatus(Xdg64Status.PREPARING);
167	                    order.updateStatus(Xdg64Status.IN_WAREHOUSE);
168	
169	
170	                    Xnn94 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
171	                    order.assignWarehouseStorage(warehouseStorage);
172	                    order.updateStatus(Xdg64Status.COMPLETED);
173	                } else {
174	
175	                    order.updateStatus(Xdg64Status.PAYMENT_COMPLETED);
176	                    order.updateStatus(Xdg64Status.PREPARING);
177	                }
178	            } catch (Xnn94Exception e) {
179	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
180	                throw new Xdx92Exception("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
181	            } catch (Exception e) {
182	                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
183	                throw new Xmv95Exception("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
184	            }
185	
186	
187	            try {
188	                orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
189	                    orderBid.updateStatus(Xtz73Status.MATCHED);
190	                });
191	            } catch (Exception e) {
192	                log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
193	
194	            }
195	        } catch (Exception e) {
196	            if (e instanceof Xdg64Exception) {
197	                throw e;
198	            }
199	            log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
